import{_ as a,o as t,c as s,ae as i}from"./chunks/framework.Co1PSFSm.js";const u=JSON.parse('{"title":"Notes, Limitations, and Gotchas","description":"","frontmatter":{},"headers":[],"relativePath":"notes.md","filePath":"notes.md"}'),o={name:"notes.md"};function n(r,e,l,c,d,h){return t(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="notes-limitations-and-gotchas" tabindex="-1">Notes, Limitations, and Gotchas <a class="header-anchor" href="#notes-limitations-and-gotchas" aria-label="Permalink to &quot;Notes, Limitations, and Gotchas&quot;">​</a></h1><h2 id="instance-variable-access-restrictions-private-protected" tabindex="-1">Instance Variable Access Restrictions (Private / Protected) <a class="header-anchor" href="#instance-variable-access-restrictions-private-protected" aria-label="Permalink to &quot;Instance Variable Access Restrictions (Private / Protected)&quot;">​</a></h2><p>All instance variables are publicly accessible. Extending the private / protected access controls to cover instance variables may be added in the future. A general convention of adding an leading underscore to things which shouldn&#39;t be used externally (i.e. private members / methods) is encouraged. If true private members are needed, another alternative is to create scope-limited lookup tables or functions within the file where the class is defined.</p><h2 id="classes-are-immutable-and-should-be-atomically-defined" tabindex="-1">Classes are Immutable and Should be Atomically Defined <a class="header-anchor" href="#classes-are-immutable-and-should-be-atomically-defined" aria-label="Permalink to &quot;Classes are Immutable and Should be Atomically Defined&quot;">​</a></h2><p>One gotcha of LibTSMClass is that all methods and static fields of a class must be fully defined before that class is subclassed or instantiated. This means that changing the definition of a class at runtime is not supported, and may lead to undefined behavior. Along the same lines, once a class&#39;s methods are defined, they may not be changed later on.</p><h2 id="highly-performant-base-classes" tabindex="-1">Highly-Performant Base Classes <a class="header-anchor" href="#highly-performant-base-classes" aria-label="Permalink to &quot;Highly-Performant Base Classes&quot;">​</a></h2><p>Inheritance is one of the most powerful uses of OOP, and LibTSMClass fully supports it. However, for cases where performance is of the utmost importance, LibTSMClass is heavily optimized to reduce the overhead of a class which does not subclass anything to be as close to direct table access as possible (without metamethod calls).</p>',7)])])}const f=a(o,[["render",n]]);export{u as __pageData,f as default};
